<template>
	<view class="container">
		<uv-navbar leftText="返回" :fixed="false" title="分组" :safeAreaInsetTop="true">
			<template v-slot:left>
				<view class="uv-nav-slot">
					<uv-icon name="arrow-left" size="19" @click="back"></uv-icon>
					<uv-line direction="column" :hairline="false" length="16" margin="0 8px"></uv-line>
					<uv-icon name="home" size="20" @click="back"></uv-icon>
				</view>
			</template>
		</uv-navbar>
		<view class="tag-flex">
			<view class="uv-page__tag-item" v-for="(item, index) in tagList" :key="index">
				<uv-tags shape="circle" size="large" :text="item.title" closable :plain="true" type="success"
					:name="index" :show="item.close" @close="delTag(item,index)">
				</uv-tags>
			</view>
			<view class="uv-page__tag-item">
				<uv-tags shape="circle" size="large" icon="plus" :text="'新增'" :plain="false" type="success"
					@click="addTag">
				</uv-tags>
			</view>
		</view>

		<view>
			<uv-popup ref="popup" mode="bottom">
				<uv-input placeholder="分类名称" v-if="statue" v-model="tag" @input="tagName" @clear="addTag"></uv-input>
				<uv-button type="success" text="添加" @click="addTagClass"></uv-button>
			</uv-popup>

		</view>
	</view>
</template>

<script>
	export default {
		data() {
			return {
				openId: '',
				tagList: [],
				tag: '',
				statue: true
			}
		},
		onLoad() {
			this.openId = this.$store.state.openId
			console.log(this.$store.state.openId)
			this.getTagList()
		},
		methods: {
			back() {
				uni.navigateBack()
			},
			delTag(item,index) {
				console.log(item)
				console.log(index)
				item.close = false
				wx.cloud.callFunction({
					name: 'deleteClass',
					data: {
						"openId": item.openId,
						"title": item.title,
						"_id": item._id
					},
					complete: res => {
						console.log('callFunction test result: ', res)
						this.getTagList()
					}
				})
			},
			addTag() {
				this.tag = ""
				// console.log(this.tag)
				// this.statue = true
				this.$refs.popup.open();
			},
			tagName(e) {
				this.tag = e
				// console.log(e)
			},
			getTagList() {
				wx.cloud.callFunction({
					name: 'getClass',
					data: {
						"openId": this.openId,
					},
					complete: res => {
						console.log('callFunction test result: ', res)
						if (res.result.data.length > 0) {
							this.tagList = res.result.data
							this.tagList.forEach((item, index) => {
								item.close = true
							})
						}

					}
				})
			},
			addTagClass() {
				console.log(this.openId)
				console.log(this.tag)
				wx.cloud.callFunction({
					name: 'saveClass',
					data: {
						"openId": this.openId,
						"title": this.tag

					},
					complete: res => {
						console.log('callFunction test result: ', res)
						this.tag = '';
						// console.log(this.tag)
						this.$refs.popup.close();
						this.getTagList()
						// this.statue = false
					}
				})
			}
		},
		mounted() {
			// console.log(this.$store.state.openId)
		}
	}
</script>

